from fastapi import HTTPException
from ascii_colors import ASCIIColors
import re
from pathlib import Path

def sanitize_path(
    path: str, 
    allow_absolute_path: bool = False, 
    error_text: str = "Absolute database path detected", 
    exception_text: str = "Detected an attempt of path traversal or command injection. Are you kidding me?"
) -> str:
    """
    Sanitize a given file path by checking for potentially dangerous patterns and unauthorized characters.

    Parameters:
    path (str): The file path to sanitize.
    allow_absolute_path (bool): Whether to allow absolute paths.
    error_text (str): Error message for absolute path detection.
    exception_text (str): Detailed exception message for path traversal or command injection.

    Returns:
    str: The sanitized file path.
    """
    if path is None:
        return path

    path = path.replace('\\', '/')
    if not allow_absolute_path and path.strip().startswith("/"):
        raise HTTPException(status_code=400, detail=exception_text)

    suspicious_patterns = re.compile(r'(\.\.+)|(/+/)|(\$\(.*\))')
    if suspicious_patterns.search(str(path)) or ((not allow_absolute_path) and Path(path).is_absolute()):
        ASCIIColors.error(error_text)
        raise HTTPException(status_code=400, detail=exception_text)

    unauthorized_chars = set('!"#$%&\'()*+,;<=>?@[]^`{|}~')
    if any(char in unauthorized_chars for char in path):
        raise HTTPException(status_code=400, detail=exception_text)

    if not allow_absolute_path:
        path = path.lstrip('/')

    return path

def test_sanitize_path():
    assert sanitize_path("safe/path") == "safe/path"
    assert sanitize_path("/absolute/path", allow_absolute_path=True) == "absolute/path"
    try:
        sanitize_path("/absolute/path", allow_absolute_path=False)
    except HTTPException as e:
        assert e.status_code == 400
    try:
        sanitize_path("../path/traversal")
    except HTTPException as e:
        assert e.status_code == 400
    try:
        sanitize_path("$(injection)")
    except HTTPException as e:
        assert e.status_code == 400
    try:
        sanitize_path("invalid|path")
    except HTTPException as e:
        assert e.status_code == 400
